// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        // Admissible domain: any address may be set as the new owner by the admin.
        // The admin is the deployer (this test contract), which set up in the constructor.
        try c.setOwner(newOwner) {
            // General rule: after a successful admin call, the owner is exactly newOwner.
            assertTrue(c.owner() == newOwner);
        } catch {
            // setOwner never reverts when called by the admin, so this branch is unreachable
            // for admissible inputs; keep the same single assertion via a trivially-failing path.
            assertTrue(false);
        }
    }
}
